{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise TypeError("nodes must be an array")
    if not isinstance(required_symbols, list):
        raise TypeError("required_symbols must be an array")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise TypeError("required_symbols must contain strings")

    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    seen_ids = set()
    records = []
    for node in nodes:
        if not isinstance(node, dict):
            raise TypeError("each node must be an object")
        if any(field not in node for field in required_node_fields):
            raise ValueError("node is missing a required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id in seen_ids:
            raise ValueError("node ids must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise TypeError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise TypeError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int):
            raise TypeError("depth must be an integer")
        if depth < 0:
            raise ValueError("depth must be non-negative")
        if not isinstance(removable, bool):
            raise TypeError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise TypeError("utility must be numeric")
        if not math.isfinite(float(utility)):
            raise ValueError("utility must be finite")

        seen_ids.add(node_id)
        records.append({
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
        })

    ids = set(seen_ids)
    roots = [node for node in records if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("the tree must have exactly one root")
    for node in records:
        if node["parent"] is not None and node["parent"] not in ids:
            raise ValueError("parent must reference an existing node")

    children = {node["id"]: [] for node in records}
    for node in records:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])

    by_id = {node["id"]: node for node in records}
    active = set(ids)
    removed = []
    ordered = sorted(records, key=lambda node: (-node["depth"], node["id"]))
    required = set(required_symbols)

    for node in ordered:
        node_id = node["id"]
        if not node["removable"] or node_id not in active:
            continue
        if any(child in active for child in children[node_id]):
            continue
        remaining_symbols = {by_id[active_id]["symbol"] for active_id in active if active_id != node_id}
        if not required.issubset(remaining_symbols):
            continue
        active.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(active),
    }
